INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('power-quest','advanced','What is the maximum power point of a solar cell?',ARRAY['Operating point of maximum P = V×I','Maximum voltage point','Maximum current point','Open circuit voltage'],0,'MPP: dP/dV = 0 on the IV curve.',20),
('power-quest','advanced','What is MPPT?',ARRAY['Maximum Power Point Tracking','Maximum Power Point Transfer','Multi-Power Point Tracking','Maximum Power Phase Tracking'],0,'MPPT dynamically adjusts load to stay at maximum power point.',20),
('power-quest','advanced','What algorithm is commonly used for MPPT?',ARRAY['Perturb and Observe (P&O)','Newton-Raphson','Binary search','Kalman filter'],0,'P&O: perturb voltage, observe power change direction.',20),
('power-quest','advanced','What is the incremental conductance MPPT method?',ARRAY['dP/dV = 0 → dI/dV = -I/V','dI/dV = I/V','dV/dI = 0','dP/dI = V'],0,'At MPP: dI/dV = -I/V (incremental = negative conductance).',20),
('power-quest','advanced','What is the fill factor of a solar cell?',ARRAY['FF = (Vm × Im) / (Voc × Isc)','Voc / Isc','Vm / Voc','Im / Isc'],0,'FF measures how ''square'' the IV curve is.',20),
('power-quest','advanced','What is the efficiency of a typical commercial solar cell?',ARRAY['15-22%','5-10%','30-40%','50-60%'],0,'Commercial Si cells: 15-22% efficiency.',20),
('power-quest','advanced','What is the Shockley-Queisser limit?',ARRAY['~33.7% max efficiency for single-junction cell','~50%','~10%','~100%'],0,'Theoretical max for single-junction Si under AM1.5G.',20),
('power-quest','advanced','How do you exceed the Shockley-Queisser limit?',ARRAY['Multi-junction (tandem) cells','Thicker cells','More sunlight','Higher voltage'],0,'Tandem cells stack different bandgap materials.',20),
('power-quest','advanced','What is a battery management system (BMS)?',ARRAY['Monitors and protects battery cells','Charges batteries','Discharges batteries','Measures voltage only'],0,'BMS: balancing, protection, SOC estimation.',20),
('power-quest','advanced','What is state of charge (SOC)?',ARRAY['Remaining capacity as percentage','Total capacity','Voltage level','Current level'],0,'SOC = remaining energy / full capacity × 100%.',20),
('power-quest','advanced','What is depth of discharge (DOD)?',ARRAY['Percentage of capacity used','Percentage remaining','Total capacity','Charging level'],0,'DOD = 100% - SOC.',20),
('power-quest','advanced','What is Coulomb counting for SOC?',ARRAY['Integrating current over time','Measuring voltage','Measuring temperature','Measuring impedance'],0,'SOC = SOC₀ - ∫I dt / capacity.',20),
('power-quest','advanced','What is cell balancing?',ARRAY['Equalizing charge across battery cells','Charging cells faster','Discharging cells','Measuring cell voltage'],0,'Balancing prevents overcharge/overdischarge of cells.',20),
('power-quest','advanced','What is the difference between active and passive balancing?',ARRAY['Active transfers energy; passive dissipates','Active is slower','Passive is more efficient','No difference'],0,'Passive: bleed resistors. Active: transfer between cells.',20),
('power-quest','advanced','What is a supercapacitor?',ARRAY['High-capacity electrochemical capacitor','Small capacitor','DC-DC converter','Battery type'],0,'Supercapacitors: high energy density, fast charge/discharge.',20),
('power-quest','advanced','What is the energy density comparison: battery vs supercapacitor?',ARRAY['Battery higher energy, supercap higher power','Supercap higher energy','Same','Battery higher power'],0,'Batteries: high Wh/kg. Supercaps: high W/kg.',20),
('power-quest','advanced','What is a smart grid?',ARRAY['Grid with two-way communication and control','Traditional grid','Off-grid system','Microgrid'],0,'Smart grid: sensors, meters, automated control.',20),
('power-quest','advanced','What is demand response?',ARRAY['Adjusting load based on grid conditions','Generating more power','Reducing voltage','Increasing frequency'],0,'Demand response shifts load to reduce peak demand.',20),
('power-quest','advanced','What is load shedding?',ARRAY['Disconnecting loads during overload','Adding more loads','Increasing generation','Reducing frequency'],0,'Load shedding prevents grid collapse.',20),
('power-quest','advanced','What is the purpose of a grid-tie inverter?',ARRAY['Synchronize with grid and feed power','Convert AC to DC','Store energy','Isolate from grid'],0,'Grid-tie inverter: phase-locked to grid, anti-islanding.',20),
('power-quest','advanced','What is anti-islanding?',ARRAY['Detecting grid failure and disconnecting','Connecting to grid','Generating more power','Reducing output'],0,'Anti-islanding protects lineworkers during outages.',20),
('power-quest','advanced','What is a microgrid?',ARRAY['Localized grid that can operate independently','Large grid','National grid','Off-grid only'],0,'Microgrid: can disconnect from main grid and self-supply.',20),
('power-quest','advanced','What is distributed generation?',ARRAY['Small-scale generation near load','Centralized generation','Nuclear power','Grid-scale solar'],0,'DG: solar panels, wind turbines, fuel cells near consumers.',20),
('power-quest','advanced','What is net metering?',ARRAY['Feeding excess generation back to grid','Measuring total consumption','Measuring total generation','Fixed-rate billing'],0,'Net metering credits prosumers for excess energy.',20),
('power-quest','advanced','What is the capacity factor of a power plant?',ARRAY['Actual output / Rated capacity × 100%','Efficiency','Power factor','Load factor'],0,'Capacity factor = average output / maximum output.',20),
('power-quest','advanced','What is base load?',ARRAY['Minimum continuous demand on grid','Peak demand','Average demand','Off-peak demand'],0,'Base load plants run continuously (nuclear, coal).',20),
('power-quest','advanced','What is peak load?',ARRAY['Maximum demand period','Minimum demand','Average demand','Off-peak'],0,'Peaking plants handle short-term high demand.',20),
('power-quest','advanced','What is load following?',ARRAY['Adjusting generation to match demand','Adjusting demand to match generation','Fixed generation','Fixed demand'],0,'Load following: plants ramp output with demand changes.',20),
('power-quest','advanced','What is spinning reserve?',ARRAY['Ready-to-deliver extra capacity','Off-line reserve','Long-term reserve','Maintenance reserve'],0,'Spinning reserve: synchronized, ready in minutes.',20),
('power-quest','advanced','What is FACTS?',ARRAY['Flexible AC Transmission System','Fast AC Transfer System','Flexible Alternative Current System','Full AC Transmission Standard'],0,'FACTS: power electronic devices for grid control.',20),
('power-quest','advanced','What is a STATCOM?',ARRAY['Static Synchronous Compensator','Static Switching Compensator','Synchronous Static Converter','Static System Compensator'],0,'STATCOM: voltage-source inverter for reactive power.',20),
('power-quest','advanced','What is an SVC?',ARRAY['Static Var Compensator','Static Voltage Compensator','Switching Var Converter','Static Variable Compensator'],0,'SVC: thyristor-controlled reactive power compensation.',20),
('power-quest','advanced','What is HVDC?',ARRAY['High Voltage DC transmission','High Voltage Direct Current','High Voltage Distribution Control','High Voltage DC Converter'],0,'HVDC: efficient long-distance power transmission.',20),
('power-quest','advanced','What is the advantage of HVDC over HVAC?',ARRAY['Lower losses for long distances','Higher losses','Same losses','No advantage'],0,'HVDC: no skin effect, no reactive losses, lower line loss.',20),
('power-quest','advanced','What is a DC-DC converter efficiency typically?',ARRAY['85-98%','50-60%','30-40%','100%'],0,'Modern DC-DC converters: 85-98% efficient.',20),
('power-quest','advanced','What is synchronous rectification?',ARRAY['Using MOSFETs instead of diodes','Using diodes only','Using IGBTs','Using thyristors'],0,'Synchronous rectification: MOSFETs reduce conduction losses.',20),
('power-quest','advanced','What is interleaving in converters?',ARRAY['Running multiple phases in parallel','Running at higher frequency','Using more inductors','Adding more capacitors'],0,'Interleaving reduces ripple and increases effective frequency.',20),
('power-quest','advanced','What is the benefit of multiphase converters?',ARRAY['Lower ripple, better thermal distribution','Higher voltage','Lower frequency','Simpler design'],0,'Multiphase: ripple cancellation, shared current, less stress.',20),
('power-quest','advanced','What is a resonant converter?',ARRAY['Uses LC resonance for soft switching','Uses resistors','Uses diodes only','Hard switching'],0,'Resonant converters achieve ZVS/ZCS for high efficiency.',20),
('power-quest','advanced','What is an LLC resonant converter?',ARRAY['L-L-C tank for ZVS','RLC circuit','LC circuit','RC circuit'],0,'LLC: two inductors + capacitor, high efficiency at varied loads.',20),
('power-quest','advanced','What is active power factor correction?',ARRAY['Boost converter for PF ≈ 1','Capacitor only','Inductor only','Transformer'],0,'Active PFC: boost pre-regulator shapes input current.',20),
('power-quest','advanced','What is the THD target for active PFC?',ARRAY['< 5%','< 50%','< 20%','< 10%'],0,'Active PFC achieves THD < 5% and PF > 0.99.',20),
('power-quest','advanced','What is a UPS?',ARRAY['Uninterruptible Power Supply','Universal Power Source','Underground Power System','Unified Power Supply'],0,'UPS provides backup power during outages.',20),
('power-quest','advanced','What are the types of UPS?',ARRAY['Online, line-interactive, offline','AC and DC','Single and three-phase','Small and large'],0,'Online: double conversion. Line-interactive: AVR. Offline: standby.',20),
('power-quest','advanced','What is double conversion in online UPS?',ARRAY['AC→DC→AC for clean output','AC→DC only','DC→AC only','AC→AC'],0,'Online UPS: always converts through DC link for isolation.',20),
('power-quest','advanced','What is galvanic isolation?',ARRAY['No direct electrical connection between circuits','Direct connection','Shared ground','Shared neutral'],0,'Isolation via transformer prevents ground loops.',20),
('power-quest','advanced','What is creepage distance?',ARRAY['Shortest path along insulator surface','Air gap distance','Insulator thickness','Conductor length'],0,'Creepage: surface path for safety standards.',20),
('power-quest','advanced','What is clearance distance?',ARRAY['Shortest air gap between conductors','Surface distance','Insulator length','Wire length'],0,'Clearance: air gap for dielectric strength.',20),
('power-quest','advanced','What is the function of an optocoupler in power supplies?',ARRAY['Signal isolation between primary and secondary','Amplification','Rectification','Filtering'],0,'Optocouplers provide feedback isolation in isolated supplies.',20),
('power-quest','advanced','What is a flyback converter?',ARRAY['Isolated buck-boost using transformer','Non-isolated buck','Non-isolated boost','Forward converter'],0,'Flyback: energy stored in transformer during on-time, released during off-time.',20);